-- =====================================================================================
--  2026-11-09 게시판 서식·사진 + Soul Saver 스팀 공지 옮기기 (운영 DB 에 한 번 실행)
--  SQL Editor → New query → 이 파일 전체 붙여 넣기 → Run. 여러 번 실행해도 안전하다.
--  구조 변경(1~3)은 schema.sql 에도 반영되어 있다. 공지 데이터(4)는 이 파일에만 있다.
--
--  1. posts.fmt: 'text'(옛 글, 글자 그대로) / 'html'(서식 글, 화면에 넣기 직전 DOMPurify 로 정화).
--  2. 본문 길이: check 는 60,000자까지, 일반 회원은 트리거로 20,000자·링크 3개까지(운영자 글은 예외).
--  3. 사진 버킷 board: 누구나 읽기(공개 URL), 올리기는 로그인한 본인 폴더(uid/)에만·하루 30장,
--     png·jpeg·webp 만(SVG 금지), 2MB 까지, 덮어쓰기 금지, 지우기는 본인 또는 운영자.
--  4. Soul Saver 스팀 공지(한국어판)를 원래 날짜로 「공지」에 넣는다(tools/steam_news.mjs 로 만듦).
-- =====================================================================================

-- ---------- 1·2. 서식 글 + 길이 제한 -------------------------------------------------------
alter table public.posts add column if not exists fmt text not null default 'text';
alter table public.posts drop constraint if exists posts_fmt_check;
alter table public.posts add constraint posts_fmt_check check (fmt in ('text', 'html'));
alter table public.posts drop constraint if exists posts_body_check;
alter table public.posts add constraint posts_body_check check (char_length(body) between 1 and 60000);

-- 운영자 판정은 글쓴이 기준(넣을 때 RLS 가 author_id = auth.uid() 를 강제하므로 남을 사칭할 수 없다).
create or replace function public.posts_body_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if exists (select 1 from public.profiles where id = new.author_id and role = 'admin') then
    return new;
  end if;
  if char_length(new.body) > 20000 then
    raise exception 'body_limit: 본문은 서식을 포함해 20,000자까지 쓸 수 있습니다. / Posts are limited to 20,000 characters including formatting.'
      using errcode = 'P0001';
  end if;
  if new.fmt = 'html' and (char_length(new.body) - char_length(replace(lower(new.body), '<a ', ''))) / 3 > 3 then
    raise exception 'body_limit: 링크는 한 글에 3개까지 넣을 수 있습니다. / Up to 3 links per post.'
      using errcode = 'P0001';
  end if;
  return new;
end;
$$;
drop trigger if exists posts_body_limit on public.posts;
create trigger posts_body_limit before insert or update on public.posts
  for each row execute function public.posts_body_limit();

-- ---------- 3. 사진 버킷 ------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('board', 'board', true, 2097152, array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do update
  set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- 오늘(24시간) 내가 올린 사진 수. 경로 첫 폴더가 uid 라 그것으로 센다.
create or replace function public.board_uploads_today()
returns int
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::int from storage.objects
  where bucket_id = 'board' and name like auth.uid()::text || '/%' and created_at > now() - interval '1 day';
$$;
revoke execute on function public.board_uploads_today() from public, anon;
grant execute on function public.board_uploads_today() to authenticated;

drop policy if exists board_img_insert on storage.objects;
create policy board_img_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'board'
    and (storage.foldername(name))[1] = auth.uid()::text
    and name ~ '^[0-9a-f-]{36}/[A-Za-z0-9_-]{1,64}\.(webp|jpg|png)$'
    and public.board_uploads_today() < 30
  );
-- 공개 URL 은 정책 없이 읽힌다. API 목록 조회(select)는 본인 폴더·운영자만(지우기에 필요).
drop policy if exists board_img_select on storage.objects;
create policy board_img_select on storage.objects
  for select to authenticated
  using (bucket_id = 'board' and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin()));
drop policy if exists board_img_delete on storage.objects;
create policy board_img_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'board' and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin()));
-- update 정책은 만들지 않는다(덮어쓰기 금지).

-- ---------- 4. 스팀 공지 --------------------------------------------------------------------
-- >>> steam notices (tools/steam_news.mjs 가 만든 구간, 손으로 고치지 말 것)
-- Soul Saver 스팀 공지 15개(한국어판). 작성 시각은 스팀 원래 날짜. 이미 있으면(제목+날짜) 건너뛴다.
-- 작성 시각 고정·도배 제한 트리거를 이 블록 안에서만 끄고 다시 켠다. do 블록은 한 덩어리라 중간에 실패해도 트리거가 꺼진 채 남지 않는다.
do $do$
declare
  admin_id uuid := (select id from public.profiles where role = 'admin' order by created_at limit 1);
begin
  if admin_id is null then
    raise notice '관리자 계정이 없어 스팀 공지를 넣지 않았습니다.';
    return;
  end if;
  alter table public.posts disable trigger posts_stamp_insert;
  alter table public.posts disable trigger posts_rate_limit;
  insert into public.posts (author_id, category, game, title, body, fmt, created_at)
  select admin_id, 'notice', 'soulsaver', $q$1.1 대형 업데이트 — 판마다 달라지는 이벤트, 영혼 각인 · 영혼의 무게 · 유물, 스팀 순위표$q$, $q$<p><span class="fs-l c-gray">출시 뒤 일곱 번의 업데이트를 한 번에 정리했습니다. 새 콘텐츠 · 보기 쉬워진 화면 · 무한 모드 · 밸런스.</span></p>출시 뒤 사흘 동안 1.1.0부터 1.1.6까지 일곱 번 업데이트했습니다. 작은 업데이트를 자주 내느라 공지가 늦었습니다. 바뀐 것을 한 번에 정리합니다.<br>밸런스 수치는 혼란을 막기 위해 <b>출시 때(1.0.7) 값 → 지금 값</b>으로만 적었습니다.<br><br><img src="https://clan.akamai.steamstatic.com/images/46473597/5ba5a38534979fdd92ca650306e68510ec880389.png" alt=""><h3>🎲 판마다 달라지는 판</h3>같은 장이라도 매번 다른 일이 벌어집니다.<ul><li><b>장 중반 무작위 이벤트 6종</b> — 습격 · 엘리트 · 황금 고블린 · 저주받은 상자(2장부터) · 영혼 제단 지키기 · 정예 무리. 3초 전에 배너와 화살표로 알려 드립니다</li><li><b>보물 상자 개편</b> — 보상 12종 중 무작위 3택. 일반 70% · 희귀 25% · 전설 5%(중간 보스 · 정예 상자는 15%). 전설 상자는 룰렛이 돌아 보상 3~5개가 한꺼번에 쏟아지고, 재료를 모은 스킬 진화가 있으면 그 자리에서 진화합니다</li><li><b>봉인된 석관과 유물</b> — 2장부터 장마다 60% 확률로 석관이 나타납니다. 가까이 1.5초 머물면 열리고, 다른 영웅의 스킬 8종 중 하나를 유물로 고릅니다(한 판 최대 2개, 쿨타임 1.5배). 새 [Q] 유물 칸(패드 Y)</li><li><b>부서지는 맵 물체</b> — 장마다 항아리 · 화로 · 나무통 · 영혼 수정 6~8개. 몸으로 부딪치면 코인 · 고기 · 금화 · 자석 · 시간 정지 · 정화가 나옵니다</li><li><b>영혼 부스러기 무리</b> — 한꺼번에 몰려오는 작은 영혼들을 쓸어 담는 재미. 1장은 적도 더 빨리, 더 많이 나옵니다</li></ul><h3>🔱 새 도전: 영혼 각인 · 영혼의 무게</h3><ul><li><b>영혼 각인</b> (이야기 모드 「쉬움」 클리어 뒤) — 판을 시작할 때 3택 1, 2장 · 3장 보스를 쓰러뜨릴 때마다 한 장 더. 장점과 단점이 함께 있는 각인 12종(처음 4종 + 기록으로 8종 해금). 예: 유리 대포(공격력 +40% · 최대 체력 −30%), 영혼의 밀물(경험치 · 코인 +25% · 적 생성 간격 −25%). 각인마다 포인트 배율 최대 ×1.35</li><li><b>영혼의 무게</b> (「어려움」 클리어 뒤, 어려움 판에만) — 무게 1~6, 단계마다 시련이 하나씩 쌓이고 포인트 +5%씩(최대 +30%). 1 잡몹 · 엘리트 체력 +15% · 2 한 화면 적 +3씩 · 3 보스 결계 게이지 35% 빨리 · 4 물약 · 고기 회복 −40% · 5 카드 다시 뽑기 없음 · 6 최후의 보루 없음. 영웅마다 가장 무거운 클리어를 캐릭터 · 결과 화면에 표시</li></ul><h3>🌟 더 오래 성장: 각성 · 초월 카드 · 스킬 진화</h3><ul><li><b>각성</b> — 이야기 모드 3장 보스를 쓰러뜨리면 각성 3택</li><li><b>초월 카드 11종</b> — 최대 레벨(50 · 무한 80) 뒤 경험치 막대 3번마다 3택 1. 숫자가 아니라 판의 규칙이 바뀝니다: 메아리 · 영혼 수확 · 시간의 틈 · 연금 손 · 그림자 분신 · 중력장 · 역전 · 맵 지배 · 연쇄 붕괴 · 영혼 보호막 · 영혼불 발자국(같은 카드는 다음 단계, 최대 3)</li><li><b>스킬 진화가 확실히 세집니다</b> — 진화 18종의 재료 피해 ×1.25~1.8(명궁의 호흡 ×1.8 · 가시 숲 ×1.7 · 천검 궤적 ×1.6 등), 진화 고유 효과 9종 상향(폭풍의 길 60 → 120% · 사냥꾼의 낙인 120 → 200% · 칼날 곡예 150 → 200% 등). 진화 순간 슬로모션 · 「진화!」 연출, 카드에 「진화까지 1단계!」 표시</li></ul><h3>📖 발견형 도감</h3>진화 · 유물 · 각인 · 비밀은 직접 얻은 것만 도감에 열립니다(못 얻은 것은 실루엣과 힌트 한 줄). 수집 대상 154개, 수집률 25 · 50 · 75 · 100%마다 2,000 · 4,000 · 8,000 · 15,000P, 100%에는 전설 이펙트 스킨 「별의 축복」. 스포일러를 원하면 설정 → 게임 「도감 모두 보기」.<h3>👁 보기 쉬워진 것 · 손맛</h3><ul><li><b>평타가 한눈에</b> — 모든 영웅의 평타에 영웅색 테두리 · 빛 · 잔상. 판정은 보이는 크기 그대로, 빠른 총알이 적을 뚫고 지나가지 않습니다</li><li><b>안내 메시지 새 단장</b> — 큰 알림 · 오른쪽 위 알림 · 도움말로 정리. 설정 → 화면 「안내 메시지 크기」(보통 / 크게 / 아주 크게)</li><li><b>키 표시</b> — 스킬 · 유물을 얻는 순간 어느 키인지 크게 알려 주고, 칸 아래에 키캡</li><li><b>단계 표시</b> — 「0→1/5」 숫자 대신 칸이 차오르는 모양, 수치는 「지금 ▶ 다음」</li><li><b>결과 화면</b> — 다음 목표 3줄, 「같은 설정으로 다시」 · 「캐릭터 바꿔 다시」. 같은 캐릭터 두 번째 판부터 시작 이야기 건너뜀</li><li><b>손맛</b> — 보스 처치 슬로모션, 적 피격 번쩍임, 명중음, 이어 줍는 코인 소리, 처치 100 · 250 · 500 · 1,000마다 코인 10 · 25 · 50 · 100</li><li>글자 겹침 · 가림 · 잘 안 보이는 색, 끊기던 소리 등 100여 곳 수정</li></ul><h3>♾ 무한 모드</h3><ul><li><b>한계 돌파</b> — 개발자와 개발자 엄마를 모두 쓰러뜨려도 끝나지 않습니다. 클리어 기록 · 업적은 그대로, 5초 뒤 「한계 돌파!」. 적은 끝없이 강해지고 기록은 쓰러질 때까지 늘어납니다</li><li><b>최종 국면 개편</b> — 개발자 엄마는 30분이 아니라 개발자를 쓰러뜨린 뒤 잡몹 3,000마리를 잡으면 강림합니다(화면 위에 남은 수 표시). 두 보스와 싸우는 동안 다른 적은 나오지 않고, 그 사이에는 잡몹이 3배로</li><li><b>개발자 · 개발자 엄마 전용 배경음</b> 추가, 보스전 중 배경음이 일반 곡으로 바뀌던 문제 수정</li></ul><h3>🏆 스팀 순위표</h3>메인 메뉴 오른쪽 위 「순위표」에서 무한 모드 · 일일 도전(오늘) 순위를 봅니다. 전체 상위 100 · 내 주변 ±5 · 친구, 영웅 · 보스 처치 · 버틴 시간까지. 무한 모드 결과 화면에 「순위 보기」, 일일 도전 창에 「전체 순위 보기」. 순위 창을 열면 이 PC의 예전 최고 기록도 올라갑니다.<h3>⚖️ 밸런스 조정</h3>1.1 사이에 여러 번 바뀐 값은 출시 때 → 지금 값 하나로 적었습니다.<br><br><b>전체</b><ul><li>플레이어가 적 · 보스에게 주는 모든 피해(평타 · 스킬 · 필살기 · 진화 · 초월 · 유물) ×0.8</li></ul><b>장 · 적</b><ul><li>1장 적 밀도: 나오는 간격 배율 1.9 → 1.3 · 한 화면 최대 수 배율 0.5 → 0.8</li><li>잡몹 · 엘리트 · 중간 보스 체력(장 보스 제외): 1장 약 1.6배 · 2장 약 0.94배 · 3장 약 1.35배 · 4장 약 1.6배 · 무한 모드 1.4배 — 1장 → 2장에서 갑자기 어려워지던 계단을 완만하게</li><li>잡몹이 주는 피해: 2장 0.8 → 0.65 · 3장 1.08 → 1.0</li><li>적 스킬 피해: 접촉 피해의 100% → 80%(자폭 제외), 심연 거상 균열은 추가로 ×0.75</li><li>리치 왕 체력 0.88 → 0.75 · 공격 ×0.85, 지옥의 군주 공격 ×1.3 → ×1.1, 거울의 군주 체력 1.65 → 1.8</li></ul><b>영웅</b><ul><li><b>검사</b> — 보스를 다른 영웅의 두 배 속도로 잡으면서 사망률은 가장 낮아 크게 조정했습니다. 체력 1.3 → 1.15 · 공격력 3.4 → 1.75 · 고유 스킬 위력 2 → 0.98 · 회전 베기 300~800% → 200~550% · 휘두르는 동안 받는 피해 절반 0.3 → 0.2초 · 벤 적당 회복 0.3 → 0.1(흡혈 베기 0.8 / 1.3 / 1.8 → 0.45 / 0.8 / 1.15) · 날아가는 검기 40 / 60 / 80% → 30 / 45 / 60%</li><li><b>거너</b> — 일제 사격이 보스도 조준합니다(보스 피해 50%, 보스 혼자 남은 구간에서 필살기가 무용하던 문제). 쌍발 총구 · 심판의 삼연발 덤 총알 60 → 40%, 처치 파편 40 → 30%, 천둥 장전 150 → 120%, 영혼 트리 「쌍발 총구 강화」 단계마다 +25 → +5%, 다른 진화 강화 +25 → +15%</li><li><b>시계공</b> — 이중 톱니 85 → 70% · 분침 +40 / 60 / 80 / 100% → +30 / 45 / 60 / 75% · 되감기 400 → 500%</li><li><b>우체부</b> 다발 배송 덧붙는 편지 40 → 55% · <b>유령</b> 체력 0.8 → 0.9 · <b>연금술사</b> 공격 속도 0.75 → 0.8</li><li>형태 단련 I~III(다른 영웅) 평타 피해 +12 → +5%</li></ul><b>카드 · 영혼 트리 · 상점</b><ul><li>각성: 파괴 피해 +50 → +35% · 질풍 간격 −30 → −25% · 영혼 치명 +20 / +80% → +15 / +60%</li><li>영혼 트리 연사 강화 II~IV −8 → −5% · 무기 화력 III~V +10 → +6%, 처참한 일격 2.6 → 2.4배</li><li>성장 카드 힘 +3 → +2% · 손놀림 +2 → +1%, 쌍권총 · 사신 숙련 「기억」 −8 → −5%</li><li>떠돌이 상점 공격력: 매번 +25% → 처음 +25%, 살 때마다 오르는 양 ×0.85(최저 +7.5%)</li><li>전설의 힘 · 상자 「힘」: 지금 공격력 ×1.1 · ×1.05 → 기본 공격력의 +10% · +5%</li><li>무한 모드 보스 전리품 공격 +12 → +8% · 발사 간격 −8 → −5%</li><li>영혼 정련 비용: 40에서 +10씩 → 40에서 ×5씩(40 · 200 · 1,000 · 5,000 …)</li></ul><b>포인트 · 코인</b><ul><li>포인트 배율 보통 ×1 → ×1.3 · 어려움 ×1 → ×1.5, 저주받은 장마다 ×1.15</li><li>장 클리어 +200 × 장 번호, 최종 클리어 +1,500P(일일 도전 제외)</li></ul><b>무한 모드</b><ul><li>개발자 체력 10만 → 20만 · 개발자 엄마 30만 → 40만</li></ul><h3>🐛 수정</h3><ul><li>보스전 중 배경음이 일반 곡으로 바뀌던 문제</li><li>떠돌이 상점을 닫으면 근처 다른 제단이 바로 또 열리던 문제</li><li>공격 키를 E · F · C 로 바꾸면 스킬 키와 겹쳐 스킬이 함께 나가던 문제</li><li>적을 한 번 때리면 하얗게 남던 문제, 황금 고블린에 닿으면 보호막이 깎이던 문제</li><li>순위 창이 떠 있을 때 결과 화면 [R] 재시작이 먹던 문제, 일일 도전 창 ESC 가 다른 창까지 닫던 문제</li><li>이어하기 뒤 공격력이 저장 때보다 커지던 문제</li><li>무한 모드 클리어 보너스(1,500P)가 지급되지 않던 문제, 개발자 · 개발자 엄마가 쓰러질 때 배경음이 튀던 문제</li><li>도감 · 툴팁 설명이 바뀐 규칙과 다르던 문제</li></ul><h3>💬 의견을 들려주세요</h3>밸런스는 플레이 기록을 보면서 계속 다듬고 있습니다. 버그나 불편한 점, 밸런스 의견은 스팀 토론 게시판에 남겨 주세요. 하나하나 읽고 빠르게 고치겠습니다.<br>체험판에도 해당되는 변경(평타 · 안내 메시지 · 맵 물체 · 밸런스)이 함께 반영됐습니다.<br>버전별 자세한 내용은 게임 안 메인 메뉴 → 패치노트에서 볼 수 있습니다.$q$, 'html', to_timestamp(1792090230)
  where not exists (select 1 from public.posts where category = 'notice' and title = $q$1.1 대형 업데이트 — 판마다 달라지는 이벤트, 영혼 각인 · 영혼의 무게 · 유물, 스팀 순위표$q$ and created_at = to_timestamp(1792090230));
  insert into public.posts (author_id, category, game, title, body, fmt, created_at)
  select admin_id, 'notice', 'soulsaver', $q$핫픽스 - 프레임 저하 수정$q$, $q$<p><span class="fs-l c-gray">판이 갈수록 느려지던 렉을 고치고 프레임 설정을 추가했습니다.</span></p><p>플레이 중 프레임이 크게 떨어진다는 제보를 받고 긴급 업데이트를 준비했습니다. 불편을 드려 죄송합니다.</p><h3>🛠️ 프레임 저하 수정</h3><ul><li>판이 진행될수록 프레임이 점점 떨어지던 문제를 고쳤습니다. 오래 플레이할수록, 일시정지 중에도 느려지던 렉이 사라집니다.</li><li>특히 내장 그래픽 PC와 무한 모드에서 화면을 그리는 부담을 줄였습니다.</li><li>적이 많을 때 화면을 그리는 부담과 계산량을 줄였습니다. 게임 플레이와 겉모습은 그대로입니다.</li></ul><h3>⚙️ 프레임 설정 추가</h3><ul><li>설정 「화면」 탭에서 최대 프레임(30 · 60 · 120 · 144 · 제한 없음)을 고를 수 있습니다.</li><li>수직 동기화를 켜고 끌 수 있습니다.</li><li>화면 구석에 프레임(FPS)을 표시할 수 있습니다.</li></ul><p>여전히 렉이 있다면 사용하시는 PC 사양과 함께 커뮤니티 토론 게시판에 알려 주세요. 빠르게 확인하겠습니다.</p>$q$, 'html', to_timestamp(1792229044)
  where not exists (select 1 from public.posts where category = 'notice' and title = $q$핫픽스 - 프레임 저하 수정$q$ and created_at = to_timestamp(1792229044));
  insert into public.posts (author_id, category, game, title, body, fmt, created_at)
  select admin_id, 'notice', 'soulsaver', $q$V1.1.1 업데이트 — 왕들의 영토 · 한 판 더 · 개발자와 엄마의 새 공격$q$, $q$<p><span class="fs-l c-gray">왕들의 영토, 영혼 계약, 개발자와 엄마의 새 공격, 편의성 개선과 많은 버그 수정을 담았습니다.</span></p><p>무한 모드를 뒤덮는 왕들의 영토부터 판마다 새로운 목표, 개발자와 엄마의 새 공격까지 — 이번 업데이트에서 바뀐 내용을 소개합니다.</p><h2>왕들의 영토</h2><p>영혼을 구하는 여정에 큰 업데이트가 찾아왔습니다! 무한 모드가 훨씬 깊어지고, 더 편하게 즐길 수 있게 되었습니다.</p><h3>👑 왕들의 영토</h3><p>무한 모드에서 보스를 쓰러뜨리면, 그 왕의 영토가 쓰러진 자리부터 파동처럼 사막을 덮습니다.</p><ul><li>묘비와 영혼 수정이 솟아 길과 탄을 막습니다. 어디서 쏘느냐가 중요해집니다.</li><li>용암 웅덩이는 밟으면 피해를 입고, 점액 늪은 모두를 느리게 합니다.</li><li>15분 「최후의 시간」이 시작되면 모래 폭풍이 지형을 집어삼킵니다.</li></ul><h3>💾 무한 모드 저장 · 이어하기</h3><ul><li>무한 모드도 메인 메뉴로 나가거나 게임을 끄면 저장되고, 「이어하기」로 같은 지점부터 다시 할 수 있습니다.</li><li>일일 도전은 공정한 순위를 위해 저장되지 않습니다.</li></ul><h3>⚔️ 보스는 기다리지 않습니다</h3><ul><li>보스를 3분 넘게 못 쓰러뜨리면 다음 보스가 함께 나옵니다(동시에 최대 2마리).</li><li>오래 버틴 보스는 모래 폭풍에 풍화되어 받는 피해가 점점 늘어납니다.</li><li>15분 「최후의 시간」은 보스를 하나 이상 쓰러뜨린 판에만 열립니다.</li><li>개발자 · 개발자 엄마와 싸우는 동안 약한 적들이 몰려옵니다.</li></ul><h3>✨ 손맛과 편의</h3><ul><li>피격 시 체력바에 효과가 추가됩니다!</li><li>탄이 더 잘 보입니다. 내 탄과 적 탄에 어두운 테두리를 더하고 그림을 조금 키웠습니다(맞는 판정은 그대로입니다).</li><li>도적의 회전 표창은 던진 표창이 그대로 꺾여 돌아옵니다.</li><li>맵의 통이 부서진 뒤 40초마다 하나씩 다시 생깁니다.</li><li>무한 모드 초반이 더 쉬워지고, 첫 보스가 더 늦게 나옵니다.</li></ul><h3>⚖️ 밸런스 조정</h3><ul><li>무한 모드 처음 5분: 잡몹 · 보스 체력 ×0.5, 받는 피해 ×0.6 (5~9분에 서서히 원래대로)</li><li>무한 모드 첫 보스 등장: 1분 30초 → 4분</li><li>개발자 · 개발자 엄마 필살기 예고 시간: 개발자 ×0.6, 엄마 ×0.5</li><li>도적 진화 「환영 연막」: 연막 안 적 공격이 모두 빗나감 → 40% 확률로 빗나감</li></ul><h2>한 판 더</h2><p>영혼을 구하는 여정에 큰 업데이트가 찾아왔습니다! 판마다 새 목표가 생기고, 보스는 더 영리해졌으며, 더 부드럽고 편하게 즐길 수 있게 되었습니다.</p><h3>📜 영혼 계약</h3><ul><li>판마다 목표 3개가 주어지고, 이루면 바로 포인트를 받습니다. 이루지 못해도 벌칙은 없습니다.</li><li>메인 메뉴의 계약 보드 45칸을 채우면 새 유물 9종과 칭호가 열립니다.</li></ul><h3>👻 망자의 전령 · 기억 조각</h3><ul><li>쓰러지면 상황에 맞는 한마디가 들려옵니다.</li><li>영웅마다 기억 조각 6장을 모아 도감 「기억」 탭에서 읽을 수 있습니다.</li></ul><h3>🏆 새 목표와 보상</h3><ul><li>무한 모드는 보통 클리어, 일일 도전은 쉬움 클리어로 열립니다. 이미 클리어했다면 바로 열립니다.</li><li>지도 제작자 · 시계공 · 유령도 이야기 모드에서 여는 길이 생겼습니다.</li><li>무한 모드에서 5 · 10 · 15 · 20분 등을 처음 넘기면 포인트를 받습니다. 이미 넘긴 기록도 메인 메뉴 「받기」에서 받을 수 있습니다.</li><li>일일 도전에 5 · 10 · 15분 보상, 연속 출석과 완주 보상이 생기고, 규칙이 7종에서 14종으로 늘었습니다.</li></ul><h3>🌀 공간 침식</h3><p>무한 모드에서 보스가 둘 이상 함께 있으면 필살기 게이지가 하나로 합쳐집니다. 어느 보스를 때려도 같은 게이지가 찹니다.</p><ul><li>게이지가 가득 차면 각자의 결계 대신, 아레나 전체를 덮는 거대한 결계 「공간 침식」이 15초 동안 펼쳐집니다.</li><li>그 안에서는 모든 보스의 결계 공격이 더 짧은 간격으로 함께 쏟아집니다. 예고 시간은 그대로입니다.</li><li>천천히 떠도는 「고요의 눈」 안에는 땅을 치는 공격이 떨어지지 않습니다.</li></ul><h3>💻 개발자 · 엄마의 결계</h3><ul><li>개발자는 「디버그 모드」를 펼칩니다. 브레이크포인트 · 한 줄씩 실행 · 버그 대량 발생 · 무한 루프에 이어, 마지막에는 「강제 종료」가 기다립니다.</li><li>개발자 엄마는 「엄마의 대청소」를 펼칩니다. 등짝 스매싱 · 청소기 · 빨래 널기 · 잔소리 폭격에 이어, 통금 시간이 되면 결계가 좁아집니다.</li></ul><h3>🎯 빈틈</h3><ul><li>보스와 중간 보스에게 빛나는 빈틈이 생깁니다. 직접 조준한 공격으로 맞히면 피해가 크게 늘어납니다.</li><li>탄은 +75%, 근접 공격과 샷건은 +40%, 던진 공격의 직격은 +60% 피해를 줍니다.</li><li>궁수의 「완벽!」 화살과 시계공의 「정각」 톱니가 빈틈에 맞으면 「완벽한 빈틈!」이 뜨며 더 크게 늘어납니다.</li></ul><h3>🧠 기억하는 보스</h3><ul><li>보스의 체력이 정해진 값에 닿으면, 그때까지 가장 많이 맞은 공격을 기억하고 막아 냅니다.</li><li>다른 공격으로 기억을 깨면 보스가 잠시 휘청이며 받는 피해가 25% 늘어납니다.</li></ul><h3>✨ 편의 기능</h3><ul><li>ESC 메뉴에서 지금 가진 스킬을 한눈에 볼 수 있고, 일시정지 중 아이콘에 마우스를 올리면 설명이 나옵니다.</li><li>빌드 자세히 보기 · 기록 창 · 로딩 화면 · 도감 검색 · 결과 복사를 추가했습니다.</li><li>스팀 오버레이를 열거나 게임패드가 빠지면 자동으로 일시정지합니다. 전투 중에는 커서가 창 밖으로 나가지 않습니다.</li><li>게임 안의 모든 설명 문구를 더 읽기 쉽게 다듬었습니다.</li></ul><h3>⚙️ 설정</h3><ul><li>접근성 · 표시 탭을 새로 만들었습니다. 공격 고정 · 필살기 토글 · 대사 속도 · 움직임 줄이기 · 빠른 연출 · 전투 통계를 고를 수 있습니다.</li><li>「화면」 탭에 「그래픽 품질」(높음 · 낮음)과 모니터 선택을 추가했습니다. 「낮음」은 잔상 · 불꽃 · 빛 번짐 같은 꾸밈 효과만 줄입니다.</li><li>해상도 · 그래픽 품질 · 최대 프레임 · 모니터를 펼쳐서 고르는 목록으로 바꿨습니다.</li></ul><h3>⚡ 최적화</h3><ul><li>적과 탄이 많이 몰리는 후반 · 무한 모드 · 보스전에서 프레임이 더 안정적입니다.</li><li>오래 플레이할수록 조금씩 쌓이던 메모리를 정리했습니다.</li><li>개발자를 쓰러뜨린 뒤 적이 너무 많이 나와 느려지던 문제를 고쳤습니다.</li></ul><h3>🌱 체험판</h3><ul><li>체험판이 초원과 킹 슬라임으로 바뀌었습니다. 정식판의 첫 장과 같은 흐름을 즐길 수 있습니다.</li><li>거너 · 검사에 더해 유령으로도 플레이할 수 있습니다.</li></ul><h3>🛠️ 버그 수정</h3><ul><li>회전 표창이 아무것에도 닿지 않았는데 일찍 꺾여 돌아오던 문제를 고쳤습니다.</li><li>무한 모드 · 일일 도전의 배경음이 128초마다 갑자기 바뀌던 문제를 고쳤습니다. 이제 보스를 쓰러뜨릴 때 다음 곡으로 넘어갑니다.</li><li>스킬 아이콘의 단계 칸 중 가운데 칸이 깨져 보이던 문제를 고쳤습니다.</li><li>오른쪽 위 알림이 영혼 트리 버튼에 가려지던 문제를 고쳤습니다.</li><li>무한 모드 기록이 다음 결과 화면에 섞이던 문제를 고쳤습니다.</li></ul><h3>⚖️ 밸런스 조정</h3><ul><li>개발자 체력: 200,000 → 100,000</li><li>개발자 엄마 체력: 400,000 → 200,000</li><li>개발자 엄마 강림에 필요한 영혼: 3,000 → 1,000</li><li>보스 보상 가운데 칸: 영혼 조각 +40~70 → 보물 상자 보상 (희귀 60% · 일반 25% · 전설 15%)</li><li>초월 카드 간격 (이야기 모드): 막대 3번 → 2번 (무한 모드 · 일일 도전은 3번 그대로)</li><li>무한 모드 잡몹 포인트: 늘 ×1 → 2,000마리까지 ×1, 그 뒤 ×0.5, 8,000마리 뒤 ×0.2</li><li>무한 모드 클리어 보너스: 1,500P → 5,000P</li><li>영혼의 무게 포인트: 무게마다 +5% → +8%</li><li>영혼 정련 비용 (이야기 모드): 40 · 200 · 1,000 · 5,000 → 60 · 180 · 540 · 1,620 · 4,860</li><li>도적 진화 「환영 연막」: 연막 안에서 적의 공격이 40% 확률로 빗나감 → 연막 안에서 받는 피해 90% 감소</li></ul><h2>편의성 개선 · 버그 수정</h2><p>V1.3 업데이트 뒤 찾은 문제들을 고치고, 결계 속 전투를 더 편하게 다듬었습니다.</p><h3>✨ 편의성 개선</h3><ul><li>결계 · 공간 침식 중에는 용암 웅덩이가 피해를 주지 않고, 늪도 느려지게 하지 않습니다. (0.6초마다 6 피해 → 피해 없음)</li><li>공간 침식 중 결계 공격이 아닌 피해는 한 대에 최대 체력의 25%까지만 받습니다. (40% → 25%)</li><li>시전 중인 보스도 필살기 게이지가 찬 뒤 최대 3초 안에 시전을 끊고 결계를 펼칩니다. 결계가 언제 올지 알기 쉬워졌습니다.</li><li>보스 보상 가운데 칸에 「생명」 · 「회복」이 더는 나오지 않습니다.</li><li>「고요의 눈」이 웅덩이 위에 생기지 않습니다.</li></ul><h3>🛠️ 버그 수정</h3><ul><li>무한 모드에서 보스를 쓰러뜨려도 「왕들의 영토」 땅이 바뀌지 않던 문제를 고쳤습니다. 이제 영토가 번지고 용암 · 늪이 생깁니다.</li><li>15분 「최후의 시간」이 결계 · 공간 침식 도중에 시작되던 문제를 고쳤습니다.</li><li>보스가 여럿일 때 체력바와 「기억」 글자가 겹치던 문제, 보스 넷의 체력바가 화면을 너무 가리던 문제를 고쳤습니다.</li><li>엄마의 잔소리 글자가 체력바와 일시정지 화면을 가리던 문제를 고쳤습니다.</li><li>메인 메뉴 · 결과 화면에서 일부 효과음이 나지 않던 문제와, 일시정지 메뉴에서 적 설명이 버튼을 가리던 문제를 고쳤습니다.</li><li>이어하기 때 보스 위치가 어긋나거나 「풍화」 알림이 다시 뜨던 문제를 고쳤습니다. 보스 보상 가운데 칸도 이어할 때마다 다시 뽑히지 않고 처음 뽑은 칸 그대로 남습니다.</li><li>보스 등장 연출이 선택 창 위에 겹치던 문제와, 드물게 적이 비정상적으로 커지던 문제를 고쳤습니다.</li></ul><h2>개발자와 엄마의 새 공격</h2><p>무한 모드의 마지막 두 보스가 영웅 필살기 흉내 말고도 자기다운 공격을 쓰기 시작합니다. 판이 멈출 수 있던 문제들도 모두 고쳤습니다.</p><h3>💻 개발자의 새 공격</h3><ul><li>라이브 코딩: 코드 한 줄이 탄이 되어 날아옵니다. 띄어쓰기 자리가 빈틈입니다.</li><li>범위 선택: 사각형으로 드래그한 뒤 Del 키로 지웁니다. 체력이 줄면 Ctrl+V 로 한 번 더 붙여 넣습니다.</li><li>빌드 실패: 빌드가 다 차면 실패하며 터집니다.</li><li>오류 창: 경고 창이 뜨고, 「확인」 자리로 가야 안전합니다.</li><li>로딩 중…: 빙글 도는 고리가 조여 듭니다.</li><li>스택 오버플로: 블록 탑이 쌓였다가 무너집니다.</li></ul><h3>🧹 엄마의 새 공격</h3><ul><li>슬리퍼 투척: 슬리퍼가 날아와 벽에 튕깁니다.</li><li>효자손: 효자손을 크게 휘두릅니다.</li><li>타임 세일!: 할인 쿠폰을 따라 매장을 휘젓고 다닙니다.</li><li>빗자루질: 화면을 가로질러 쓸어 버립니다. 빗자루 사이 빈틈으로 피하세요.</li><li>엄친아: 엄친아 메달이 쫓아옵니다.</li><li>불 끄고 자!: 불빛이 지나갈 때 움직이면 들킵니다. 자는 척하세요!</li></ul><p>모든 공격은 먼저 경고가 보이고, 결계 · 공간 침식이 시작되면 바로 멈춥니다.</p><h3>✨ 편의성 개선</h3><ul><li>새 로딩 화면: 검은 화면 대신 로딩바와 함께 지금 영웅이 달립니다.</li><li>불 장판을 그을린 땅 위에 불꽃이 넘실대는 모습으로 새로 그렸습니다. (영웅의 불 공격 · 지옥의 군주의 불 웅덩이)</li><li>이펙트 스킨 · 전설 스킨의 연출이 훨씬 크고 잘 보입니다.</li><li>쉬움을 클리어하면 보통 · 어려움과 함께 무한 모드까지 열립니다. 이미 쉬움을 클리어했다면 바로 열립니다.</li><li>무한 모드에서 개발자가 나타난 뒤에도 떠돌이 상점이 1분마다 찾아옵니다.</li><li>게임 안 패치노트를 스팀 공지와 똑같이 맞췄습니다.</li><li>거너가 뇌운(사슬 번개 필살기)을 쓰는 동안에도 총을 쏠 수 있습니다.</li><li>무한 모드 · 일일 도전 중에 게임을 끄면 지금까지의 기록이 순위표에 올라갑니다.</li><li>빈틈이 금이 간 심장처럼 두근거리고 조준 표시가 조여 들어, 더 약점처럼 보입니다.</li></ul><h3>🛠️ 버그 수정</h3><ul><li>결과 화면이 메인 메뉴와 다음 판까지 화면에 남아 겹쳐 보이던 문제를 고쳤습니다.</li><li>무한 모드 이어하기에서 시간이 00:00에서 멈추던 문제를 고쳤습니다. 15분 「최후의 시간」과 적 증가도 제대로 진행됩니다.</li><li>보스가 영원히 공격을 받지 않던 문제를 고쳤습니다.</li><li>게이지가 가득 차도 공간 침식이 펼쳐지지 않고, 15분 「최후의 시간」과 다음 보스까지 멈추던 문제를 고쳤습니다.</li><li>보스가 기술 도중 끊겨 공중에 떠 있던 문제 등 보스전이 멈출 수 있던 문제를 더 막았습니다.</li></ul><h3>🦸 영웅 밸런스</h3><p>유령에 비해 약하던 영웅들의 화력을 크게 올렸습니다.</p><ul><li>거너: 공격력 ×1.15 → ×1.7</li><li>검사: 공격력 ×1.75 → ×2.8</li><li>도적: 공격력 ×1.0 → ×1.6</li><li>궁수: 공격력 ×1.25 → ×1.8</li><li>연금술사: 공격력 ×0.8 → ×1.2 · 필살기 충전 ×1.2 → ×1.1 (더 빨리 참)</li><li>지도 제작자: 공격력 ×1.0 → ×1.15</li><li>시계공: 공격력 ×1.0 → ×1.5 · 계약 「팔백 개의 톱니」 → 「육백 개의 톱니」 (톱니 800개 → 600개)</li><li>우체부: 공격력 ×0.8 → ×1.2</li><li>유령: 처치할 때 영혼이 생길 확률 20% → 10% · 최대 영혼 4 → 3 (영혼 수호 5 · 6 · 7 → 4 · 5 · 6) · 빙의가 끝난 뒤 무적 0.65초 → 0.3초</li></ul><h3>⚖️ 밸런스 조정</h3><ul><li>모든 적의 체력: 40% 감소 (잡몹 · 엘리트 · 중간 보스 · 보스 모두)</li><li>개발자 체력: 100,000 → 60,000</li><li>개발자 엄마 체력: 200,000 → 120,000</li><li>모든 영웅의 모든 피해: 20% 증가</li><li>지도 제작자 피해: 약 9% 감소 (공격력 배율 ×1.1 → ×1.0)</li><li>한계 돌파(개발자 엄마까지 처치한 뒤) 적의 공격력: 그대로 → 1분마다 ×1.12씩 끝없이 강해짐</li><li>무한 모드 최대 레벨: 80 → 50 (이야기 모드와 같음 · 이제 무한 모드에서도 모든 스킬을 진화할 수는 없습니다)</li><li>개발자 결계 게이지 차는 속도: ×1 → ×2.5</li><li>개발자 엄마 결계 게이지 차는 속도: ×1 → ×4</li></ul><p>플레이해 주시는 모든 분께 감사드립니다. 의견은 언제든 커뮤니티 토론 게시판에 남겨 주세요!</p>$q$, 'html', to_timestamp(1792379576)
  where not exists (select 1 from public.posts where category = 'notice' and title = $q$V1.1.1 업데이트 — 왕들의 영토 · 한 판 더 · 개발자와 엄마의 새 공격$q$ and created_at = to_timestamp(1792379576));
  insert into public.posts (author_id, category, game, title, body, fmt, created_at)
  select admin_id, 'notice', 'soulsaver', $q$V1.2 대규모 업데이트 — 빌드 갈래$q$, $q$<p><span class="fs-l c-gray">영웅마다 전혀 다르게 싸우는 빌드 갈래 5개가 생겼습니다. 같은 영웅도 이제 매판 다른 판이 됩니다.</span></p><p>이번 업데이트의 중심은 「빌드 갈래」입니다. 지금까지는 한 판에 카드 대부분을 얻어 매판 비슷한 모습이 되었습니다. 이제 영웅마다 공격 방식 자체가 바뀌는 갈래 5개 가운데 한두 개만 골라 깊게 파게 됩니다.</p><h3>🌿 빌드 갈래는 이렇게 동작합니다</h3><ul><li>판을 시작하면 입문 카드 3장 가운데 하나를 고릅니다. 입문 카드는 공격 방식을 바꾸고, 대가도 함께 붙습니다.</li><li>갈래 카드를 모으면 공명 I · 공명 II 가 열리고, 효과가 질적으로 바뀝니다. 갈래 카드를 모두 채우면 완성(진화)이 열립니다.</li><li>갈림길에서 두 번째 갈래를 고르거나, 한 갈래만 깊게 파는 「외길」을 고릅니다. 외길은 카드 단계가 하나 더 늘고 마지막 「극의」가 열립니다.</li><li>두 갈래를 섞으면 생기는 교차 시너지가 영웅마다 있습니다.</li><li>레벨업에는 갈래와 상관없이 모든 카드가 나옵니다. 고른 갈래에 맞는 카드를 모으면 공명 · 극의가 열리고, 다르게 골라도 됩니다. 최근에 고른 갈래는 판 시작 때 덜 나와 매판 다른 빌드를 만나게 됩니다.</li></ul><h3>⚔️ 영웅별 갈래</h3><p><b>거너</b>: 관통 저격 (멈춰서 모아 쏘는 관통 저격탄) · 도탄 난사 (큰 탄창 · 튕기는 난사) · 화염 과열 (장전 대신 열 게이지 · 과열 폭발) · 산탄 돌격 (탄창 4 산탄 · 장전 돌진) · 포탑 설치 (장전할 때 포탑 · 진지 방어)</p><p><b>검사</b>: 검기 (휘두를 때마다 검기 · 안전 거리) · 받아치기 (막기 0.25초 · 반격) · 피의 맹세 (체력을 바쳐 흡혈 · 근접 지속) · 검무 (미끄러지며 베기 · 기동) · 회오리 (원형 베기 · 모으며 베기)</p><p><b>도적</b>: 출혈 (5중첩 출혈 · 전염) · 그림자 (돌진 2회 · 미끼 분신) · 회귀 칼날 (되돌아오는 표창 · 탄 경제) · 질주 암살 (긴 돌진 직접 피해 · 순간 화력) · 광란 (처치마다 빨라짐 · 무리)</p><p><b>궁수</b>: 장궁 (길게 당긴 관통 화살) · 속사 (누르는 동안 연사 · 기동 무리) · 덫 (완벽 화살이 덫 · 지역 장악) · 바람 (당기며 달리기 · 생존) · 천공 (화살비 중심 · 지역 섬멸)</p><p><b>연금술사</b>: 늪 (모든 플라스크가 웅덩이 · 지역) · 빙결 (얼리고 산산조각 · 제어) · 연쇄 폭발 (자폭까지 무기로 · 무리) · 조수 (처음부터 호문쿨루스 · 자동 전투) · 원소 촉매 (순서 맞춰 붕괴 · 보스)</p><p><b>지도 제작자</b>: 정밀 측량 (네 획 사각형 · 무리 일괄) · 일필 (도형 대신 굵은 한 획) · 먹물 (획이 잉크 웅덩이 · 지역) · 접지술 (지도 접기 중심 · 필살기 폭딜) · 행군 측량 (걸어간 길이 선 · 기동 생존)</p><p><b>시계공</b>: 톱니 떼 (두 개씩 튕기기 · 무리) · 대시계 (거대 정각 톱니 · 보스 폭딜) · 시간 여행 (잦은 되감기 · 무적 · 생존) · 잔상 (모든 톱니가 두 번 · 균형) · 시간 빚 (필살기 두 배 · 맞으면 손해)</p><p><b>우체부</b>: 순회 배달 (편지가 네 명을 돎 · 무리) · 무거운 소포 (느린 폭발 소포 · 밀집 무리) · 속달 (표식 폭발 중심 · 무리 폭딜) · 자전거 배달 (달리면 편지가 저절로 · 기동) · 장거리 배송 (사거리 20 · 보스 · 원거리)</p><p><b>유령</b>: 혹한 (냉기 두 배 · 무리 제어) · 산산조각 (얼린 적 부수기 · 보스 균열) · 영혼 군단 (영혼이 돌진 공격 · 자동 화력) · 사령술 (긴 빙의 · 무적 근접 폭딜) · 유체 이탈 (움직이면 접촉 무시 · 기동 생존)</p><h3>📈 성장 곡선</h3><ul><li>영웅이 주는 모든 피해가 판이 진행될수록 강해집니다: 시작 ×0.85 → 후반 ×1.15 (무한 모드 30분 · 이야기 모드 14분 기준, 한 판 평균은 그대로)</li><li>초반은 조금 더 긴장감 있게, 후반은 성장한 만큼 더 강력하게 느껴집니다.</li></ul><h3>🦸 영웅 밸런스</h3><p>고유 스킬과 지옥의 문 특수 능력에도 이제 영웅마다 위력 배율이 붙습니다. 체력과 생존력은 그대로입니다.</p><ul><li>거너: 공격력 ×1.7 → ×2.7 · 공격 속도 ×1.0 → ×1.25 · 필살기 충전 더 빠르게 · 고유 스킬 · 특수 능력 위력 ×2.0</li><li>검사: 공격력 ×2.8 → ×4.75 · 공격 속도 ×0.55 → ×0.62 · 필살기 충전 더 빠르게 · 고유 스킬 위력 ×0.98 → ×1.85 · 특수 능력 위력 ×1.9</li><li>도적: 공격력 ×1.6 → ×2.0 · 고유 스킬 위력 ×0.85 → ×1.1 · 특수 능력 위력 ×1.4</li><li>궁수: 공격력 ×1.8 → ×2.75 · 공격 속도 ×1.0 → ×1.18 · 필살기 충전 더 빠르게 · 고유 스킬 · 특수 능력 위력 ×1.8</li><li>연금술사: 공격력 ×1.2 → ×1.9 · 공격 속도 ×0.8 → ×0.96 · 필살기 충전 더 빠르게 · 고유 스킬 · 특수 능력 위력 ×1.9</li><li>시계공: 공격력 ×1.5 → ×2.65 · 공격 속도 ×0.85 → ×0.92 · 고유 스킬 · 특수 능력 위력 ×1.9</li><li>우체부: 공격력 ×1.2 → ×1.95 · 공격 속도 ×1.0 → ×1.22 · 필살기 충전 더 빠르게 · 고유 스킬 · 특수 능력 위력 ×2.0</li><li>유령: 공격력 ×1.0 → ×0.9 · 원한: 얼어붙은 적 5중첩 → 3중첩 · 동상 +15/22/29/36% → +10/15/20/25%</li><li>지도 제작자: 공격력 ×1.15 → ×1.0 · 번지는 잉크 실제 피해를 설명대로 (초당 30/50/70% → 15/25/35%) · 닫힌 도형 피해 ×2.6 → ×2.2</li></ul><h3>✨ 개선</h3><ul><li>초월 「영혼불 발자국」이 푸른 영혼불로 새로 그려졌습니다.</li><li>영웅 선택 화면의 공격력 막대가 거너를 기준(100%)으로 표시되어 영웅끼리 비교하기 쉬워졌습니다.</li><li>영혼 트리는 이제 칸을 한 번만 누르면 바로 배웁니다.</li><li>일시정지(ESC)의 「지금 가진 스킬」에서 초월을 따로 묶어 보여 줍니다.</li><li>연금술사의 불 장판(불타는 늪 · 불꽃 행진)이 그을린 땅 위에 불꽃이 넘실대는 모습으로 바뀌었습니다.</li></ul><h3>🛠️ 버그 수정</h3><ul><li>기술이 중간에 끊기면 상태가 남을 수 있던 곳들을 막았습니다. (유령 빙의 · 거너 일제 사격 · 궁수 물러서기 · 시계공 회복 · 검사 폭풍의 눈)</li><li>거너 장전이 어떤 경우에도 막히지 않도록 안전장치를 더했습니다.</li><li>일시정지(ESC) 화면에서 「이번 판 각인」 창이 스킬 목록 위에 겹쳐 고정되어, 다른 스킬 설명을 볼 수 없던 문제를 고쳤습니다.</li><li>도적 「그림자」 갈래에서 돌진을 하나 더 모아 두는 효과가 동작하지 않던 문제를 고쳤습니다.</li><li>판 시작 입문 카드를 고르기 전에 나갔다 이어하면 입문 카드가 사라지던 문제를 고쳤습니다.</li><li>도적 「질주 암살」 극의로 무적 돌진이 끝없이 이어지던 문제를 고쳤습니다.</li><li>거너 「화염 과열」의 과열 폭발이 특수 총기 장전에도 터지던 문제, 「산탄 돌격」 산탄의 효과가 알마다 겹치던 문제를 고쳤습니다.</li><li>검사 「받아치기」가 혈갑 보호막이 있으면 성공하지 않던 문제를 고쳤습니다.</li><li>무기 진화 뒤 영혼 트리의 필살기 특성 칸(거너 「타겟 수」 등)이 사라지고 진화 전 투자만 남던 문제를 고쳤습니다. 이제 무기마다 따로 올릴 수 있습니다.</li><li>개발자 엄마를 쓰러뜨린 뒤 후반에 회복 아이템이 끝없이 쌓여 렉이 생기던 문제를 고쳤습니다. (바닥에 최대 24개 · 45초 뒤 사라짐)</li><li>갈래 · 진화 · 형태가 겹칠 때 효과가 빠지거나 오히려 약해지던 카드 8곳을 고쳤습니다. (유령 · 시계공 · 지도 제작자 · 궁수 · 우체부)</li><li>그 밖에 갈래 효과 · 이어하기 · 화면 표시에서 찾은 버그 20여 개를 고쳤습니다.</li></ul><h3>⚖️ 무한 모드 조정</h3><ul><li>무한 모드 적이 주는 영혼 조각: ×1 → ×0.36 (64% 감소)</li><li>개발자 엄마 강림에 필요한 영혼: 1,000 → 500</li></ul><p>플레이해 주시는 모든 분께 감사드립니다. 마음에 드는 갈래 조합이나 너무 세거나 약한 갈래가 있다면 커뮤니티 토론 게시판에 남겨 주세요!</p>$q$, 'html', to_timestamp(1792379762)
  where not exists (select 1 from public.posts where category = 'notice' and title = $q$V1.2 대규모 업데이트 — 빌드 갈래$q$ and created_at = to_timestamp(1792379762));
  insert into public.posts (author_id, category, game, title, body, fmt, created_at)
  select admin_id, 'notice', 'soulsaver', $q$V1.2.1 밸런스 패치 — 무한 모드 30분 · 영웅 밸런스 · 피격 판정$q$, $q$<p><span class="fs-l c-gray">무한 모드 성장 속도와 영웅 화력을 맞추고, 피격 판정과 적 · 보스의 예고를 더 알아보기 쉽게 다듬었습니다.</span></p><p>무한 모드는 숙련된 플레이어가 어떤 영웅 · 어떤 갈래로든 약 30분에 개발자 엄마를 쓰러뜨리도록 맞추고 있습니다. 지금은 10분이면 성장이 끝나 15분 뒤 보스들이 몇 초 만에 쓰러졌고, 영웅마다 클리어 시간이 크게 달랐습니다. 보스 체력을 늘리는 대신 성장 속도와 최후의 시간 흐름을 바꿨습니다.</p><h3>📈 무한 모드 성장 속도</h3><ul><li>Lv 26부터 레벨업에 필요한 경험치가 점점 늘어납니다. Lv 35~49는 4.5배입니다. 이제 Lv 50은 약 10분이 아니라 22~24분쯤 됩니다.</li><li>레벨업을 쌓아 두었다가 나중에 골라도 필요한 경험치가 줄지 않습니다.</li><li>시간에 따라 오르던 무한 모드 공격력 보정(×0.82 → ×1.10)이 ×0.82로 고정됩니다.</li><li>적이 주는 영혼 조각: ×0.36 → ×0.15 · 중간 보스: ×1 → ×0.5. 대신 개발자의 체력 단계마다 영혼 조각 +30, 엄마의 체력 단계마다 +40을 얻습니다.</li><li>이야기 모드는 바뀌지 않습니다.</li></ul><h3>👑 최후의 시간</h3><ul><li>15:00에 왕 넷이 한꺼번에 깨어나지 않고, 둘씩 두 무리로 나옵니다. 앞 무리를 모두 쓰러뜨리거나 60초가 지나면 나머지 둘이 깨어납니다.</li><li>화면 위에 진행이 보입니다: 「왕 n/4」 · 「개발자 k/3」 · 「엄마 k/4」.</li><li>엄마 강림을 기다리는 영혼 구간에는 약한 적만 나오고, 경험치를 2.5배 줍니다.</li><li>최후의 시간에 적이 늘어나는 속도: 1분마다 2배 → 2분마다 2배.</li></ul><h3>🦸 영웅 밸런스</h3><ul><li>검사: 공격력 ×4.75 → ×3.3 · 고유 스킬 위력 ×1.85 → ×1.3 · 특수 능력 위력 ×1.9 → ×1.33</li><li>궁수: 공격력 ×2.75 → ×2.0 · 고유 스킬 · 특수 능력 위력 ×1.8 → ×1.3 · 바람 공명 I: 바람길 위에서 언제 놓아도 완벽 → 완벽 판정 폭 2배</li><li>궁수 기본 공격: 화살 피해 모두 ×0.8 — 「완벽!」 화살 300% → 240% · 가득 당김 220% → 176% · 속사 한 발 35% → 28% · 속사 극의 한 발 25% → 20% (덜 당긴 화살 · 장궁 관통 광선도 같은 비율)</li><li>우체부: 공격력 ×1.95 → ×1.8 · 고유 스킬 · 특수 능력 위력 ×2.0 → ×1.85</li><li>연금술사: 공격력 · 고유 스킬 · 특수 능력 위력 ×1.9 → ×2.05</li><li>거너: 공격력 ×2.7 → ×3.5 · 고유 스킬 · 특수 능력 위력 ×2.0 → ×2.6 · 포탑이 사거리 안의 보스를 먼저 쏩니다</li><li>영웅 선택 화면의 공격력 막대는 이제 고정된 기준으로 표시됩니다.</li></ul><h3>🗡️ 도적 바로잡기</h3><ul><li>출혈 폭발: 「피바다」에서 터진 적이 폭발을 두 번 맞던 문제 수정 · 터진 뒤 출혈 중첩이 비워집니다 · 남은 출혈은 최대 1.5초치만 터집니다.</li><li>출혈 갈래: 출혈 세기 = 직접 피해의 55% → 40% · 공명 I 「출혈 터짐」은 남은 출혈 최대 1.5초치 · 돌진 타격은 출혈 세기 계산에서 빠집니다 · 「질주 암살」 돌진에도 출혈 대가(직접 피해 −35%)가 붙습니다.</li><li>약한 출혈이 걸려도 더 센 출혈의 시간이 늘어나지 않습니다.</li><li>돌진: 한 번의 돌진 묶음에서 돌려받는 필살기 게이지는 합쳐서 40%까지 · 재돌진 · 연속 돌진은 새 묶음으로 세지 않습니다 · 게이지 없이 나가는 돌진은 보스에게 피해 60%.</li><li>회귀 칼날 극의 「두 번 왕복」: 두 번째 왕복 피해 100% → 50% · 탄창 환급: 매번 → 두 번 던질 때마다 한 번.</li><li>증강 「연발」은 표창 수에 맞춰 한 개의 피해가 줄어들 수 있습니다 (모든 영웅 공통).</li><li>그림자 공명 II 연막 안 치명 ×2는 분신 연막에서만 켜집니다.</li></ul><h3>🎯 피격 판정 · 전투 예고</h3><ul><li>캐릭터가 맞는 판정이 몸 아래쪽(가슴 · 배)으로 내려가고 작아집니다: 적 탄 · 패턴 판정 반지름 0.4 → 0.3, 중심 0.42 아래로. 머리 위로 스친 탄이나 머리 위쪽 장판에는 더 이상 맞지 않습니다.</li><li>적 · 보스 몸에 닿는 판정도 작아졌습니다(특히 머리 쪽). 몸 크기가 바뀌면 판정도 함께 바뀝니다.</li><li>일반 · 엘리트 적의 장판이 늘 캐릭터 한 점에 떨어지지 않고 둘레에 흩어져, 여러 적의 장판이 한 곳에 겹치지 않습니다. 가만히 서 있으면 그대로 맞습니다.</li><li>돌진하는 적이 돌진 0.3초 전에 머리 위 「!」 · 돌진 방향 예고선 · 붉은 깜빡임으로 알립니다. (높은 난이도일수록 예고가 짧아집니다)</li><li>킹 슬라임의 분열: 글 알림 대신 몸이 부풀며 머리 위에 「분열!」이 뜨고, 작은 슬라임이 떨어질 네 자리에 초록 예고 원이 먼저 그려집니다.</li><li>보스 분노 알림은 「분노!」 한 줄로 짧아지고, 보스 몸에서 붉은 충격파와 함께 보입니다.</li><li>떠돌이 상점 알림 · 보스 대사 띠가 화면 가운데에서 화면 위쪽의 반투명 배너로 옮겨져 캐릭터 주변을 가리지 않습니다.</li><li>다음 장으로 가는 문 안내선이 더 진하고 굵어지고 어두운 테두리가 생겨, 밝은 바닥의 장에서도 잘 보입니다.</li></ul><h3>✨ 새 기능</h3><ul><li>검사 받아치기: 막기에 성공해 반격을 얻는 순간 0.6초 동안 화면이 멈추고 서서히 당겨졌다 돌아옵니다. (「화면 흔들림」을 끄면 멈춤만) 반격 준비 중에는 몸 둘레에 금빛 불티와 고리가, 반격 베기에는 큰 금빛 참격과 「반격!」이 보입니다.</li><li>플레이 데이터 보내기(선택): 게임을 켜면 한 번 동의 여부를 묻습니다. 동의한 경우에만 판이 끝날 때마다 영웅 · 카드 · 결과 같은 플레이 기록을 익명으로 보내 밸런스 조정에 씁니다. 이름 · SteamID · 이메일은 보내지 않습니다. 동의하지 않아도 게임은 똑같이 즐길 수 있고, 설정 &gt; 일반에서 언제든 끌 수 있으며, 「내 데이터 삭제 요청」으로 보낸 기록의 삭제를 요청할 수 있습니다. 자세한 내용은 「전문 보기」에 있습니다.</li></ul><h3>🔧 편의성 · 버그 수정</h3><ul><li>효과음 · 마우스 감도 같은 슬라이더는 게이지 아무 곳이나 누르면 그 위치로 바로 이동합니다.</li><li>장궁 공명 II 관통 광선: 보이는 광선이 몸을 지나도 맞지 않거나, 광선 밖인데 맞던 문제를 고쳤습니다. 여러 부위로 된 적은 한 번만 맞습니다.</li><li>능력 설명을 짧고 읽기 쉽게 다듬었습니다. 판 동안 남는 효과는 「쓰러지거나 클리어할 때까지 유지」로 표기를 맞췄습니다.</li></ul><p>다음 패치에서도 실제 플레이 기록을 보며 계속 다듬겠습니다. 너무 세거나 약한 영웅 · 갈래가 있다면 커뮤니티 토론 게시판에 남겨 주세요!</p>$q$, 'html', to_timestamp(1792404622)
  where not exists (select 1 from public.posts where category = 'notice' and title = $q$V1.2.1 밸런스 패치 — 무한 모드 30분 · 영웅 밸런스 · 피격 판정$q$ and created_at = to_timestamp(1792404622));
